<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\ClientIdentity\Application\Policy\Allow\Retrieve;

use Throwable;
use Civi\Lughauth\Features\Access\ClientIdentity\Application\Usecase\Retrieve\ClientIdentityRetrieveAllowDecision;
use Civi\Lughauth\Shared\Context;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class IsAuthenticatedRetrieveAllow
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(private readonly Context $context)
    {
    }
    public function __invoke(ClientIdentityRetrieveAllowDecision $proposal): ClientIdentityRetrieveAllowDecision
    {
        $this->logDebug("Check IsAuthenticatedRetrieveAllow Client identity");
        $span = $this->startSpan("Check IsAuthenticatedRetrieveAllow Client identity");
        try {
            $userContext = $this->context->getIdentity();
            if ($proposal->isAllowed()) {
                if (! !$userContext->anonymous) {
                    $proposal->deny('Disabled if not IsAuthenticatedRetrieve');
                }
            }
            return $proposal;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
